import { Controller } from "@hotwired/stimulus"
import { formatLocalTime } from "helpers/local_time_helpers"

const REFRESH_INTERVAL = 60_000

export default class extends Controller {
  static values = { format: { type: String, default: "relative" } }

  #timer
  #observer

  connect() {
    this.update()
    this.#timer = setInterval(() => this.update(), REFRESH_INTERVAL)
    this.#observer = new MutationObserver(() => this.update())
    this.#observer.observe(this.element, { attributes: true, attributeFilter: [ "datetime" ] })
  }

  disconnect() {
    clearInterval(this.#timer)
    this.#observer?.disconnect()
  }

  formatValueChanged() {
    this.update()
  }

  update() {
    const timestamp = this.element.getAttribute("datetime")
    if (!timestamp) return

    const date = new Date(timestamp)
    const text = formatLocalTime(date, this.formatValue)

    if (text) {
      if (this.element.textContent !== text) this.element.textContent = text
      this.element.title = formatLocalTime(date, "full")
    }
  }
}
